import manifest from '../data/og-manifest.json';
import { SITE } from '../consts';

type Kind = keyof typeof manifest;

/**
 * Per-content social preview generated by `scripts/generate-og.mjs`.
 * The generated manifest keeps this in sync with what is actually on disk, so
 * an image that was never produced falls back to the site-wide default.
 */
export function ogImageFor(kind: 'articles' | 'guides', slug: string): string {
  const slugs = (manifest as Record<string, string[]>)[kind] ?? [];
  return slugs.includes(slug) ? `/og/${kind}/${slug}.png` : SITE.ogImage;
}
